// Every claim the landing page makes, in one place (10 Nov 2026). The numbers are read from the real library
// (library-index.json, generated by scripts/build-landing-index.mjs and checked by the tests), never typed by hand.
// The headline line «the biggest agent library in the world» is stated as the MISSION, not as a measured fact:
// larger collections exist by count (public GPT stores, form-bot template galleries), and a measured superlative
// that is not true is unlawful advertising in most markets. Change the wording here, not in the page.
import index from './library-index.json';

export const LIBRARY = index as unknown as {
  counts: { agents: number; fields: number; areas: number; starters: number; chains: number; places: number; sources: number; research: number };
  colors: string[];
  fields: { id: string; name: string; blurb: string; count: number; areas: { name: string; color: number; count: number }[] }[];
  agents: [name: string, field: number, color: number, id: string][];
  chains: { id: string; name: string; description: string; steps: string[] }[];
};
export const N = LIBRARY.counts;
export const fmt = (value: number) => value.toLocaleString('en-GB');
/** «1,000+» for 1,033: the round number below the real one, so the claim stays true as the library grows. */
export const plus = (value: number, step: number) => value >= step ? `${fmt(Math.floor(value / step) * step)}+` : fmt(value);

export const CLAIMS = {
  mission: 'Building the biggest agent library in the world',
  title: [`${plus(N.agents, 1000)} AI agents.`, 'One for every job you do.'],
  lead: `A ready-made agent for the work professionals repeat every week, across ${N.fields} fields. Each one follows a real working method, researches official sources and hands back finished files. Or build your own in a minute.`,
  stats: [
    { value: N.agents, label: 'ready-made agents' },
    { value: N.fields, label: 'fields of work' },
    { value: N.starters, label: 'ready questions' },
    { value: N.places, label: 'jurisdictions' },
    { value: N.sources, label: 'official sources' },
    { value: N.chains, label: 'chain agents' },
  ],
  close: 'Your next task already has an agent.',
};
